const claimed=($json.body??$json).claimed;
if(!claimed?.job||!claimed?.billingCase)return [];
const c=claimed.billingCase,job=claimed.job;
const snapshot={vatId:c.vat_id,billingAddress:c.billing_address,deliveryAddress:c.delivery_address,revision:c.current_revision??0};
const norm=x=>String(x??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');
const company=x=>norm(x).replace(/GESELLSCHAFTMITBESCHRANKTERHAFTUNG$/,'GMBH').replace(/GESELLSCHAFTMBH$/,'GMBH');
const country=String(c.delivery_address?.country??'').toUpperCase();
const vatId=norm(c.vat_id);
const eu=new Set(['AT','BE','BG','CY','CZ','DK','EE','ES','FI','FR','GR','HR','HU','IE','IT','LT','LU','LV','MT','NL','PL','PT','RO','SE','SI','SK']);
const evidence={source:'EU_VIES',checked:false,valid:null,normalizedVatId:vatId,countryCode:country,checkedAt:new Date().toISOString(),identityComparison:'NOT_AVAILABLE',addressComparison:'NOT_AVAILABLE'};
if(c.tax_review_status!=='REVIEW_REQUIRED'||c.cancelled_at||c.refunded_at||c.final_invoice_at) {
 evidence.outcome='SKIPPED';
} else if(!eu.has(country)||!vatId.startsWith(country==='GR'?'EL':country)) {
 evidence.outcome='COUNTRY_MISMATCH';
} else if(!/^[A-Z]{2}[A-Z0-9]{2,12}$/.test(vatId)||(country==='AT'&&!/^ATU\d{8}$/.test(vatId))) {
 evidence.outcome='FORMAT_INVALID';
} else {
 if(typeof this.helpers?.httpRequest!=='function')throw new Error('VIES_HTTP_HELPER_UNAVAILABLE');
 let p;
 try { p=await this.helpers.httpRequest({method:'GET',url:'https://ec.europa.eu/taxation_customs/vies/rest-api/ms/'+encodeURIComponent(country==='GR'?'EL':country)+'/vat/'+encodeURIComponent(vatId.slice(2)),headers:{Accept:'application/json'},json:true,timeout:15000}); }
 catch { p=null; }
 const code=typeof p?.userError==='string'?p.userError.toUpperCase():'';
 if(!p||typeof p.isValid!=='boolean'||(code&&!['VALID','INVALID'].includes(code))||(code==='VALID'&&!p.isValid)||(code==='INVALID'&&p.isValid)) {
  evidence.outcome='UNAVAILABLE';evidence.providerCode=code||'NETWORK_OR_RESPONSE_ERROR';
 } else {
  evidence.checked=true;evidence.valid=p.isValid;
  evidence.name=typeof p.name==='string'&&norm(p.name)?p.name.trim():null;
  evidence.address=typeof p.address==='string'&&norm(p.address)?p.address.trim():null;
  evidence.requestDate=typeof p.requestDate==='string'?p.requestDate:null;
  evidence.providerCode=code;
  const a=c.billing_address??{};
  const expectedName=company(a.company), listedName=company(evidence.name);
  evidence.identityComparison=!expectedName||!listedName?'NOT_AVAILABLE':expectedName===listedName?'MATCH':'MISMATCH';
  const expectedAddress=norm(a.street)+norm(a.zip)+norm(a.city);
  const listedAddress=norm(String(evidence.address??'').replace(new RegExp('\\b'+country+'[-\\s]*(?=\\d)','g'),''));
  evidence.addressComparison=!a.street||!a.zip||!a.city||!listedAddress?'NOT_AVAILABLE':expectedAddress===listedAddress?'MATCH':'MISMATCH';
  evidence.outcome=!p.isValid?'INVALID':
   evidence.identityComparison==='MISMATCH'||evidence.addressComparison==='MISMATCH'?'IDENTITY_MISMATCH':
   evidence.identityComparison==='MATCH'&&evidence.addressComparison==='MATCH'?'VERIFIED':'IDENTITY_UNAVAILABLE';
 }
}
return [{json:{jobId:job.id,leaseToken:job.lease_token,snapshot,evidence}}];

const r=$json.body??$json;
if(!r?.shouldAlert)return [];
const descriptions={
 INVALID:'Umsatzsteuer-ID von VIES als ungültig gemeldet',
 UNAVAILABLE:'VIES-Prüfdienst nach drei Versuchen nicht erreichbar oder ohne verwertbare Antwort; Nummer nicht als ungültig bewertet',
 IDENTITY_MISMATCH:'Umsatzsteuer-ID gültig; Firmenname oder Rechnungsanschrift weicht von VIES ab',
 IDENTITY_UNAVAILABLE:'Umsatzsteuer-ID gültig; VIES liefert nicht genügend Firmen- oder Anschriftsdaten',
 FORMAT_INVALID:'Umsatzsteuer-ID hat ein ungültiges Format',
 COUNTRY_MISMATCH:'Umsatzsteuer-ID und EU-Lieferland passen nicht zusammen',
 TAX_REVIEW:'Umsatzsteuer-ID bestätigt; bestehende Steuerbehandlung muss gesondert geprüft werden'
};
const clean=x=>String(x??'').replace(/[\r\n]+/g,' ').slice(0,500);
const v=r.validation??{};
throw new Error([
 descriptions[r.outcome]||'Umsatzsteuerprüfung: Klärung erforderlich',
 'Auftrag: '+clean(r.orderName),'USt-ID: '+clean(r.vatId),
 'Prüfversuche: '+r.attempts+' von 3; Wiederholungsabstand jeweils 5 Minuten',
 'Prüfstatus: checked='+v.checked+', valid='+v.valid+', comparison='+v.identityComparison+', addressComparison='+v.addressComparison,
 'Bei VIES gelistete Firma: '+clean(v.name||'nicht geliefert'),
 'Registeranschrift: '+clean(v.address||'nicht geliefert'),
 'Ops-Fall: https://ops.neontrip.de/ops/rechnungen?caseId='+encodeURIComponent(r.caseId),
 'Nächster Schritt: '+(r.outcome==='UNAVAILABLE'?'Prüfdienst später erneut prüfen; keine Kundenkorrektur allein wegen Nichterreichbarkeit verlangen.':'USt-ID und Firmendaten mit der Registerauskunft vergleichen und die Abweichung in OPS klären.'),
 'Die finale steuerfreie Rechnung bleibt gesperrt; andere Sperren bleiben unverändert.'
].join(' | '));
